$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; $stmt=$pdo->prepare('SELECT id,full_name,email,password_hash,role,is_active FROM users WHERE email=? LIMIT 1'); $stmt->execute([$email?:'']); $user=$stmt->fetch(); if(!$user||!password_verify($password,$user['password_hash'])||!(int)$user['is_active'])$error='Email or password is incorrect.'; else {session_regenerate_id(true);$_SESSION['csrf_token']=bin2hex(random_bytes(32));$_SESSION['user']=['id'=>(int)$user['id'],'full_name'=>$user['full_name'],'email'=>$user['email'],'role'=>$user['role']];redirect($user['role']==='admin'?'admin/dashboard.php':'student/dashboard.php');}}
start_page('Sign in'); ?><section class="card auth-card"><p class="eyebrow">PORTAL ACCESS</p><h1 class="card-title mt-2 text-2xl">Welcome back</h1><p class="muted mt-2">Sign in to continue to your Warwa account.</p><?php if($error): ?><div class="alert alert-error mt-4"><?= e($error) ?></div><?php endif ?><form method="post" class="mt-6 space-y-4"><?= csrf_field() ?><div><label class="field-label" for="email">Email address</label><input class="field" id="email" name="email" type="email" required autocomplete="email" value="<?= e($_POST['email']??'') ?>"></div><div><div class="mb-1 flex justify-between"><label class="field-label mb-0" for="password">Password</label><a class="text-xs font-bold text-teal-700" href="<?= e(app_url('forgot-password.php')) ?>">Forgot password?</a></div><div class="password-wrap"><input class="field" id="password" name="password" type="password" required autocomplete="current-password"><button type="button" class="eye-toggle" data-password-toggle="password" aria-label="Show password"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div><button class="btn-primary w-full">Sign in</button></form><p class="mt-5 text-center text-sm text-slate-500">New to Warwa? <a class="font-bold text-teal-700" href="<?= e(app_url('register.php')) ?>">Create an account</a></p></section><?php end_page(); ?>
